package com.company.tpm.security;
import com.company.tpm.authorization.*; import com.company.tpm.user.*; import org.slf4j.*; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.core.env.Environment; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class SecureBootstrapRunner implements ApplicationRunner {private static final Logger log=LoggerFactory.getLogger(SecureBootstrapRunner.class);private final Environment env;private final AppUserRepository users;private final RoleRepository roles;private final PasswordEncoder encoder;public SecureBootstrapRunner(Environment e,AppUserRepository u,RoleRepository r,PasswordEncoder p){env=e;users=u;roles=r;encoder=p;}
 @Override @Transactional public void run(ApplicationArguments args){String username=env.getProperty("BOOTSTRAP_ADMIN_USERNAME");String password=env.getProperty("BOOTSTRAP_ADMIN_PASSWORD");if(username==null||password==null)return;if(password.length()<16)throw new IllegalStateException("BOOTSTRAP_ADMIN_PASSWORD must contain at least 16 characters");if(users.findByUsernameIgnoreCase(username).isPresent())return;var role=roles.findByCode("SUPER_ADMIN").orElseThrow();var user=new AppUser(username,encoder.encode(password));user.addRole(role);users.save(user);log.warn("Initial administrator '{}' created. Remove bootstrap variables and rotate the password.",username);}}
